  "baseline_models": [
    {
      "model_id": "baseline_clear_sight_revalued_action",
      "confidence": "strong",
      "focus_anchor": "تبيّن لكم ... وزيّن لهم الشيطان أعمالهم فصدّهم عن السبيل وكانوا مستبصرين",
      "mechanism": "The construction preserves both disclosure and active discernment while placing beautification on intentional deeds and diversion on movement. The failure is therefore evaluative and behavioral, not a simple absence of evidence.",
      "activation_trace": [
        {
