      "changed_reading": {
        "before": "Their dwellings merely identify where the destroyed peoples once lived.",
        "after": "Their former places of stability are themselves stopped, material testimony to the end of that stability."
      }
    },
    {
      "model_id": "baseline_distance_hardened_into_barrier",
      "confidence": "medium",
      "focus_anchor": "الشيطان ... فصدّهم عن السبيل",
      "mechanism": "The distance and deviation images of sh-y-ṭ-n, followed by ṣadd as turning or barrier and sabīl as a traversable line, yield a spatial chain: attractive action masks incremental divergence until distance hardens into obstruction.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r05",
          "branch_key": "root_000796/B001",
          "role": "Remoteness and severance supply the growing separation from the route."
        },
        {
          "occurrence_id": "29:38/r05",
          "branch_key": "root_000796/B003",
          "role": "Crooked divergence supplies the change of bearing hidden within that separation."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Applied attractiveness conceals the route-degrading effect of the deviation."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B005",
          "role": "A mountain-like obstruction materializes accumulated divergence as a barrier."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The extended road provides the spatial line from which they are separated."
        }
      ],
      "changed_reading": {
        "before": "Satan simply persuades them not to choose the correct road.",
        "after": "Beautified conduct progressively produces distance, wrong bearing, and finally a barrier between agents and the road."
      }
    },
    {
      "model_id": "baseline_deeds_wear_competing_route",
      "confidence": "exploratory",
      "focus_anchor": "زيّن ... أعمالهم فصدّهم عن السبيل",
      "mechanism": "The peripheral worked-road branch of ʿamal lets deed and route-making overlap: beautification makes repetition inviting, repeated conduct wears a competing track, and familiarity with that track helps exclude the named path.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Visible improvement makes recurrence of the conduct attractive."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Purposive deeds provide the repeated steps that can sediment a route."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B011",
          "role": "A road made passable by use turns accumulated action into behavioral infrastructure."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Diversion supplies the exclusionary effect of the competing track."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The actual path remains the route against which the worn alternative is measured."
        }
      ],
      "changed_reading": {
        "before": "Their deeds are objects of beautification separate from the path they abandon.",
        "after": "Their conduct itself wears the rival road whose ease and familiarity make the true route harder to enter."
      }
    }
  ],
  "context_deltas": [
    {
      "model_id": "delta_social_capture_of_route",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "The invitation to follow a group-owned route, backed by a false offer to carry faults, supplies the sales pitch; added burdens and public road-cutting show attractive conduct scaling from recruitment into community-maintained obstruction.",
