        {
          "occurrence_id": "29:29/r03",
          "branch_key": "root_001240/B023",
          "role": "Forcible road obstruction materializes social path-capture as public conduct."
        },
        {
          "occurrence_id": "29:29/r05",
          "branch_key": "root_001486/B001",
          "role": "The communal assembly supplies the institution in which obstructive conduct is normalized."
        }
      ],
      "structural_cues": [
        "The imperative to follow our path is coupled to promised burden-bearing, immediately reversed by doubled burdens; later, communal wrongdoing is paired with cutting the route in the public club."
      ],
      "reader_inference": "The packet supplies rival-route speech, attempted surety, added weight, and public route-cutting; I infer that discounted responsibility enables recruitment and repeated recruitment becomes institutional obstruction. Belonging, status, or coercion rather than liability discounting remains a live alternative.",
      "changed_reading": {
        "before": "Satan privately charms individuals away from an otherwise open road.",
        "after": "Beautification can work through group promises, moral cost-laundering, and public norms that capture and physically or socially cut the route."
      }
    },
    {
      "model_id": "delta_habitation_frozen_into_sign",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "A deliberately left sign, violent shaking, and bodies clinging to the ground in their home activate the stillness within masākin: catastrophe reverses shelter's function and turns a place that held life into an evidentiary cast of its end.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Manifest disclosure makes the destroyed habitat legible to later viewers."
        },
        {
