        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Attractive presentation supplies the reinforcing surface of the obstructive practice."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B011",
          "role": "A road worn by use supplies the habit-path that counterpractice must interrupt."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Prevention supplies the focus's first inhibitory direction."
        },
        {
          "occurrence_id": "29:45/r04",
          "branch_key": "root_001273/B008",
          "role": "Setting upright supplies a stable, route-correcting posture for the practice."
        },
        {
          "occurrence_id": "29:45/r05",
          "branch_key": "root_000879/B003",
